DROP TABLE IF EXISTS community_user_audit;
DROP TABLE IF EXISTS community_audit;
DROP TABLE IF EXISTS community_appeal;
DROP TABLE IF EXISTS community_report;
DROP TABLE IF EXISTS community_review;
DROP TABLE IF EXISTS community_favorite;
DROP TABLE IF EXISTS community_wanted;
DROP TABLE IF EXISTS market_trade;
DROP TABLE IF EXISTS market_goods;
DROP TABLE IF EXISTS app_user;
CREATE TABLE app_user(id BIGINT AUTO_INCREMENT PRIMARY KEY,email VARCHAR(254) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,nickname VARCHAR(50) NOT NULL,email_verified TINYINT NOT NULL DEFAULT 1,status TINYINT NOT NULL DEFAULT 0,role VARCHAR(16) NOT NULL DEFAULT 'USER',session_version INT NOT NULL DEFAULT 0,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE market_goods(id BIGINT AUTO_INCREMENT PRIMARY KEY,seller_id BIGINT NOT NULL,title VARCHAR(100) NOT NULL,description VARCHAR(2000) NOT NULL DEFAULT '',price DECIMAL(12,2) NOT NULL,category VARCHAR(20) NOT NULL DEFAULT 'OTHER',image_urls VARCHAR(4000) NOT NULL DEFAULT '[]',status VARCHAR(16) NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE market_trade(id BIGINT AUTO_INCREMENT PRIMARY KEY,goods_id BIGINT NOT NULL,seller_id BIGINT NOT NULL,buyer_id BIGINT NOT NULL,status VARCHAR(16) NOT NULL,buyer_confirmed TINYINT DEFAULT 0,seller_confirmed TINYINT DEFAULT 0,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE community_review(id BIGINT AUTO_INCREMENT PRIMARY KEY,trade_id BIGINT NOT NULL,reviewer_id BIGINT NOT NULL,reviewee_id BIGINT NOT NULL,rating INT NOT NULL CHECK(rating BETWEEN 1 AND 5),review_text VARCHAR(1000) NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE(trade_id,reviewer_id));
CREATE TABLE community_report(id BIGINT AUTO_INCREMENT PRIMARY KEY,reporter_id BIGINT NOT NULL,target_type VARCHAR(16) NOT NULL,target_id BIGINT NOT NULL,reason VARCHAR(1000) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'OPEN',resolution VARCHAR(1000),resolver_id BIGINT,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE community_appeal(id BIGINT AUTO_INCREMENT PRIMARY KEY,report_id BIGINT NOT NULL UNIQUE,appellant_id BIGINT NOT NULL,reason VARCHAR(1000) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'OPEN',resolution VARCHAR(1000),resolver_id BIGINT,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE community_audit(id BIGINT AUTO_INCREMENT PRIMARY KEY,actor_id BIGINT NOT NULL,report_id BIGINT NOT NULL,action VARCHAR(40) NOT NULL,detail VARCHAR(1500) NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE community_user_audit(id BIGINT AUTO_INCREMENT PRIMARY KEY,actor_id BIGINT NOT NULL,target_user_id BIGINT NOT NULL,new_status INT NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE community_favorite(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,goods_id BIGINT NOT NULL,created_at DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,goods_id));
CREATE TABLE community_wanted(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,title VARCHAR(100) NOT NULL,description VARCHAR(2000) NOT NULL,max_price DECIMAL(12,2) NOT NULL CHECK(max_price>=0),category VARCHAR(20) NOT NULL DEFAULT 'OTHER',status VARCHAR(16) NOT NULL DEFAULT 'OPEN',created_at DATETIME DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
